const fs = require('fs');
const path = require('path');

function walk(dir, out = []) {
  for (const entry of fs.readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (fs.statSync(full).isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
}

const results = [];
let driveRootFolderId = '';

for (const item of $input.all()) {
  const { basePath, moduleName } = item.json;
  driveRootFolderId = item.json.driveRootFolderId;

  if (!fs.existsSync(basePath)) continue;

  for (const filePath of walk(basePath)) {
    const rel = filePath.substring(basePath.length).replace(/^[\\/]+/, '');
    const parts = rel.split(path.sep);
    const fileName = parts.pop();
    const segments = [moduleName, ...parts];
    results.push({
      json: {
        filePath,
        fileName,
        moduleName,
        relativeFolderSegments: segments,
        relativeFolderPath: segments.join('/'),
        driveRootFolderId
      }
    });
  }
}

if (results.length === 0) {
  return [{ json: { filePath: '', driveRootFolderId } }];
}

return results;

