// === Parallel Upload (bulk-dedup) ===
// Designed for large batches (10K+ files).
// Phase 1: list each unique destination folder ONCE in parallel  -> builds folderId -> Set<fileName>
// Phase 2: filter to only files that don't already exist on Drive
// Phase 3: upload the remaining files concurrently (Promise.all worker pool)
// Uses your existing 'googleDriveOAuth2Api' credential.
//
// IMPORTANT: with 10K+ files, n8n's task-runner timeout (default 300s) may need to be raised.
// Add to your n8n environment:  N8N_RUNNERS_TASK_TIMEOUT=3600

const ctx = this;
const fs = require('fs').promises;

// ---- tuning knobs ----
const UPLOAD_CONCURRENCY = 10;   // parallel upload slots (Drive user quota ~ keep <= 10-12)
const LIST_CONCURRENCY   = 16;   // parallel folder-list slots (cheap reads)
const SKIP_IF_EXISTS     = true; // false = always upload (creates duplicates)
const LIST_PAGE_SIZE     = 1000;
// ----------------------

const items = $input.all().map(i => i.json).filter(f => f && f.filePath);

async function withRetry(fn, attempts = 4, baseDelayMs = 800) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try { return await fn(); }
    catch (e) {
      lastErr = e;
      if (i < attempts - 1) await new Promise(r => setTimeout(r, baseDelayMs * Math.pow(2, i)));
    }
  }
  throw lastErr;
}

async function runPool(arr, limit, worker) {
  const out = new Array(arr.length);
  let cursor = 0;
  const runOne = async () => {
    while (true) {
      const i = cursor++;
      if (i >= arr.length) return;
      try { out[i] = await worker(arr[i], i); }
      catch (e) { out[i] = { __err: e.message || String(e) }; }
    }
  };
  await Promise.all(Array.from({ length: limit }, runOne));
  return out;
}

// ---- Phase 1: bulk listing ----
async function listFolderNames(folderId) {
  const names = new Set();
  let pageToken;
  do {
    const qs = {
      q: `'${folderId}' in parents and trashed = false`,
      fields: 'nextPageToken,files(name)',
      pageSize: String(LIST_PAGE_SIZE),
      supportsAllDrives: 'true',
      includeItemsFromAllDrives: 'true'
    };
    if (pageToken) qs.pageToken = pageToken;
    const res = await withRetry(() =>
      ctx.helpers.httpRequestWithAuthentication.call(ctx, 'googleDriveOAuth2Api', {
        method: 'GET',
        url: 'https://www.googleapis.com/drive/v3/files',
        qs,
        json: true
      })
    );
    for (const f of res.files || []) names.add(f.name);
    pageToken = res.nextPageToken;
  } while (pageToken);
  return { folderId, names };
}

const tStart = Date.now();

let existingByFolder = new Map();
let listErrors = 0;
if (SKIP_IF_EXISTS && items.length) {
  const folderIds = [...new Set(items.map(f => f.driveFolderId || f.driveRootFolderId))];
  const listed = await runPool(folderIds, LIST_CONCURRENCY, listFolderNames);
  for (const r of listed) {
    if (r && r.folderId) existingByFolder.set(r.folderId, r.names);
    else listErrors++;
  }
}
const tListed = Date.now();

// ---- Phase 2: filter ----
const toUpload = SKIP_IF_EXISTS
  ? items.filter(f => {
      const fid = f.driveFolderId || f.driveRootFolderId;
      const existing = existingByFolder.get(fid);
      return !(existing && existing.has(f.fileName));
    })
  : items.slice();

const skippedCount = items.length - toUpload.length;

// ---- Phase 3: upload ----
async function uploadMultipart(filePath, name, parentId) {
  const buffer = await fs.readFile(filePath);
  const boundary = '----n8n_' + Math.random().toString(36).slice(2);
  const CRLF = '\r\n';
  const meta = JSON.stringify({ name, parents: [parentId] });
  const body = Buffer.concat([
    Buffer.from(`--${boundary}${CRLF}Content-Type: application/json; charset=UTF-8${CRLF}${CRLF}${meta}${CRLF}`),
    Buffer.from(`--${boundary}${CRLF}Content-Type: application/octet-stream${CRLF}${CRLF}`),
    buffer,
    Buffer.from(`${CRLF}--${boundary}--${CRLF}`)
  ]);
  const res = await withRetry(() =>
    ctx.helpers.httpRequestWithAuthentication.call(ctx, 'googleDriveOAuth2Api', {
      method: 'POST',
      url: 'https://www.googleapis.com/upload/drive/v3/files',
      qs: { uploadType: 'multipart', supportsAllDrives: 'true' },
      headers: { 'Content-Type': `multipart/related; boundary=${boundary}` },
      body,
      json: false
    })
  );
  return typeof res === 'string' ? JSON.parse(res) : res;
}

async function uploadOne(file) {
  const folderId = file.driveFolderId || file.driveRootFolderId;
  try {
    const r = await uploadMultipart(file.filePath, file.fileName, folderId);
    return { fileName: file.fileName, module: file.moduleName, status: 'uploaded', id: r.id };
  } catch (e) {
    return { fileName: file.fileName, module: file.moduleName, status: 'failed', error: e.message || String(e) };
  }
}

const uploadResults = toUpload.length ? await runPool(toUpload, UPLOAD_CONCURRENCY, uploadOne) : [];
const tDone = Date.now();

const uploaded = uploadResults.filter(r => r && r.status === 'uploaded').length;
const failed   = uploadResults.filter(r => r && r.status === 'failed');

return [{
  json: {
    total: items.length,
    uploaded,
    skipped: skippedCount,
    failed: failed.length,
    listErrors,
    listMs: tListed - tStart,
    uploadMs: tDone - tListed,
    totalMs: tDone - tStart,
    failures: failed
  }
}];

const r = $input.first().json;
const secs = (ms) => (ms / 1000).toFixed(1) + 's';
return [{
  json: {
    message: `Uploaded ${r.uploaded}, skipped ${r.skipped} (already on Drive), failed ${r.failed}. List ${secs(r.listMs || 0)} + Upload ${secs(r.uploadMs || 0)} = ${secs(r.totalMs || 0)}.`,
    total: r.total,
    uploaded: r.uploaded,
    skipped: r.skipped,
    failed: r.failed,
    listMs: r.listMs,
    uploadMs: r.uploadMs,
    totalMs: r.totalMs,
    failures: r.failures || [],
    timestamp: new Date().toISOString()
  }
}];
